entries[18652] = { ["name"] = "Bauplan: Gyrofrosteisreflektor", ["text"] = "Benötigt Ingenieurskunst (260)\nBenutzen: Lehrt Euch die Herstellung eines Gyrofrosteisreflektors.\nGyrofrosteisreflektor\nWird beim Anlegen gebunden\nSchmuck\n+15 Frostwiderstand\nBenötigt Stufe 47\nBenötigt Ingenieurskunst (260)\nBenutzen: Reflektiert Frostzauber für 5 Sek. zurück auf den Zaubernden. (5 Min Abklingzeit)\nBenötigt Thoriumapparat (6), Echtsilberumwandler (2), Blauer Saphir (2), Essenz des Feuers (4), Frostöl (2), Eiskappe (4)" }
entries[18653] = { ["name"] = "Bauplan: Goblin-Überbrückungskabel XL", ["text"] = "Benötigt Ingenieurskunst (265)\nBenötigtGoblin-Ingenieur\nBenutzen: Lehrt Euch die Herstellung von Goblin-Überbrückungskabeln XL\nGoblin-Überbrückungskabel XL\nSchmuck\nBenötigt Ingenieurskunst (265)\nBenutzen: Mit Überbrückungskabeln kann man manchmal einen toten Spieler ins Leben zurückrufen. Kann nicht im Kampf verwendet werden. (30 Min Abklingzeit)\nBenötigt Thoriumapparat (2), Echtsilberumwandler (2), Verschmorte Verkabelung (2), Eisenweberseide (2), Sternrubin (2)" }
entries[18654] = { ["name"] = "Bauplan: Gnomischer Alarm-O-Bot", ["text"] = "Benötigt Ingenieurskunst (265)\nBenötigtGnomen-Ingenieur\nBenutzen: Lehrt Euch die Herstellung eines Alarm-O-Bots.\nGnomsicher Alarm-O-Bot\nBenötigt Ingenieurskunst (265)\nBenutzen: Erschafft für 10 Minuten einen Alarm-O-Bot, der in regelmäßigen Abständen einen Impuls aussendet, welcher getarnte oder unsichtbare Einheiten aufspürt. (10 Min Abklingzeit)\nBenötigt Thoriumbarren (4), Thoriumapparat (2), Unverwüstliches Leder (4), Sternrubin , Verschmorte Verkabelung" }
entries[18655] = { ["name"] = "Bauplan: Großer Rekombobulator", ["text"] = "Benötigt Ingenieurskunst (275)\nBenutzen: Lehrt Euch die Herstellung eines großen Rekombobulator.\nGroßer Rekombobulator\nSchmuck\nBenötigt Ingenieurskunst (275)\nBenutzen: Bannt Verwandlungseffekte von einem befreundeten Ziel. Stellt außerdem noch 375 bis 625 Punkt(e) Gesundheit und Mana wieder her. (5 Min Abklingzeit)\n10 Aufladungen\nBenötigt Thoriumröhre (2), Echtsilberumwandler , Runenstoff (2)" }
entries[18656] = { ["name"] = "Bauplan: Mächtige Zephyriumladung", ["text"] = "Benötigt Ingenieurskunst (275)\nBenutzen: Lehrt Euch die Herstellung von mächtigen Zephyriumladungen.\nMächtige Zephyriumladung\nBenötigt Ingenieurskunst (275)\nBenutzen: Sprengt fast jede verschlossene Tür auf.\nBenötigt Thoriumapparat (2), Dichtes Sprengpulver (3), Unverwüstliches Leder (2), Erfrischendes Quellwasser" }
entries[18657] = { ["name"] = "Bauplan: Hyperstrahlender Flammenreflektor", ["text"] = "Benötigt Ingenieurskunst (290)\nBenutzen: Lehrt Euch die Herstellung eines Hyperstrahlenden Flammenreflektors.\nHyperstrahlender Flammenreflektor\nWird beim Anlegen gebunden\nSchmuck\n+18 Feuerwiderstand\nBenötigt Stufe 53\nBenötigt Ingenieurskunst (290)\nBenutzen: Reflektiert Feuerzauber für 5 Sek. zurück auf den Zaubernden. (5 Min Abklingzeit)\nBenötigt Dunkeleisenbarren (4), Echtsilberumwandler (3), Essenz des Wassers (6), Sternrubin (4), Azerothianischer Diamant (2)" }
entries[18658] = { ["name"] = "Bauplan: Ultrablendender Schattenreflektor", ["text"] = "Benötigt Ingenieurskunst (300)\nBenutzen: Lehrt Euch die Herstellung eines Ultrablendenden Schattenreflektors.\nUltrablendender Schattenreflektor\nWird beim Anlegen gebunden\nSchmuck\n+20 Schattenwiderstand\nBenötigt Stufe 55\nBenötigt Ingenieurskunst (300)\nBenutzen: Reflektiert Schattenzauber für 5 Sek. zurück auf den Zaubernden. (5 Min Abklingzeit)\nBenötigt Dunkeleisenbarren (8), Echtsilberumwandler (4), Essenz des Lebens (6), Essenz des Untodes (4), Azerothianischer Diamant (2), Großer Opal (2)" }
